import{_ as t,a as r,b as l,c as o,d as i}from"./chunks/d96ea9decbc786364a09.CNLo_3aI.js";import{_ as n,C as s,o as h,c,j as p,a as m,E as d,a5 as f}from"./chunks/framework.DNkHA0lr.js";const I=JSON.parse('{"title":"如何借助 AI 比任何人快 10 倍地学会任何东西","description":"","frontmatter":{"title":"如何借助 AI 比任何人快 10 倍地学会任何东西","originalTitle":"How To Learn Anything 10X Faster Than Anyone With AI","date":"2025-03-01","originalUrl":"https://thedankoe.com/letters/how-to-learn-anything-10x-faster-than-anyone-with-ai/","minutes":12,"sourceHash":"528ae2f3ace1cd16c8cbcba3e20df03e2f8fb6a56bc6c4d965f3f63051e353f0","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/how-to-learn-anything-10x-faster-than-anyone-with-ai/"}]]},"headers":[],"relativePath":"letters/how-to-learn-anything-10x-faster-than-anyone-with-ai.md","filePath":"letters/how-to-learn-anything-10x-faster-than-anyone-with-ai.md"}'),u={name:"letters/how-to-learn-anything-10x-faster-than-anyone-with-ai.md"};function b(_,e,g,k,x,A){const a=s("ArticleMeta");return h(),c("div",null,[e[0]||(e[0]=p("h1",{id:"如何借助-ai-比任何人快-10-倍地学会任何东西",tabindex:"-1"},[m("如何借助 AI 比任何人快 10 倍地学会任何东西 "),p("a",{class:"header-anchor",href:"#如何借助-ai-比任何人快-10-倍地学会任何东西","aria-label":'Permalink to "如何借助 AI 比任何人快 10 倍地学会任何东西"'},"​")],-1)),d(a),e[1]||(e[1]=f('<p><a href="https://www.youtube.com/embed/FzaHX5rxU34?feature=oembed" target="_blank" rel="noreferrer">观看原文视频</a></p><p>大多数人根本不知道如何学习。</p><p>他们用教程、播客和教科书把大脑塞得满满的,但6个月后,却发现自己什么都没有学出来。</p><p>如果学习不是为了拿它去<em>做</em>点什么,那你一开始学它是为了什么?</p><p>对大多数人来说,学习已经变成了一种精神上的自我安慰。它和刷手机时获得的那种廉价多巴胺没什么区别,甚至更糟——它会让你以为自己在学东西(剧透一下:明天你就会把它忘得一干二净)。</p><p>这是残酷的真相:</p><p>你学习的速度太慢了。</p><p>而如果你能学得快10倍,你就能同样快10倍地获得成功。你能完成那个作品集项目。你能启动那门生意。你能把你对某个话题的想法表达得清清楚楚。</p><p>更进一步说,别人花6个月才能学会的东西,你也许2周就能学会。</p><p>要做到这一点,你需要学会如何学习,具体包括:</p><ul><li>门徒效应(Protege Effect)与费曼技巧(Feynman Technique)</li><li>如何针对模式识别进行优化</li><li>如何用 AI 加速这个过程</li><li>基于项目的学习方式,让你真正地<em>做</em>出点东西</li></ul><p>这将是一篇非常实用的信件。</p><p>请准备好把你的笔记打开放在旁边。</p><p>看完之后,你将拥有一条清晰的路径,能够快速学会任何东西。</p><h2 id="元技能——学会如何学习" tabindex="-1">元技能——学会如何学习 <a class="header-anchor" href="#元技能——学会如何学习" aria-label="Permalink to &quot;元技能——学会如何学习&quot;">​</a></h2><p><img src="'+t+'" alt=""></p><p>一个自由人的标志,就是他学会了如何学习。</p><p>因为如果你不自己选择要学什么,别人就会告诉你该学什么。而如果你的心智是现实世界的操作系统,那么你未来可选的选项就会被大幅限制,而你甚至都意识不到这一点。</p><p>更重要的是,在这个世界飞速变化的时代,你能做的最重要的事就是学习。而这个世界的变化速度,着实惊人。学习是最重要的单一技能,因为正是通过学习,你才能获得那些能让你把握住10年前、1年前、甚至1个月前都还不存在的机会的能力。</p><p>但大多数人学习的方式都是错的。</p><p>而学校也很少更新它们的课程体系。</p><p>下面就是你如何把自己的未来掌握在自己手中的方法。</p><h3 id="_1-为你理想的生活画一张地图" tabindex="-1">1) 为你理想的生活画一张地图 <a class="header-anchor" href="#_1-为你理想的生活画一张地图" aria-label="Permalink to &quot;1) 为你理想的生活画一张地图&quot;">​</a></h3><p>我看过无数小时教人如何学习或更快学习的视频。</p><p>它们唯一遗漏的、也是最重要的一点,就是<em>你一开始为什么要学这个。</em></p><p>人们选定一个要学的东西,<em>但它跟自己现有的技能毫无关联,也跟自己想要的生活毫无关联。</em></p><p>这是很危险的。</p><p>如果背后没有更深层的意义或清晰的目标,你根本不会<em>想要</em>学习。</p><p>你会需要更多的自律。而你很可能还是会像在学校时那样厌恶学习。或者你会觉得,自己学习纯粹是为了找一份你本来就不在乎的工作或职业。</p><p>所以这就是第一步。</p><p>为你的学习设定一个<em>目标</em>。</p><p>这样,你才能<em>感受到</em>自己正朝着自己设定的目标前进,而不是社会强加给你的那些目标。这是享受生活的一个关键要素(关于这背后的心理学原理,我这次先不展开了)。</p><p>由于我之前已经多次讲过这个话题,你可以免费填写这份<a href="https://app.kortex.co/public/document/883d9246-6dde-4794-9f54-92b8ff07d502" target="_blank" rel="noreferrer">简单人生重启表</a>(试着复制这份文档,并在填写过程中让<a href="https://x.com/thedankoe/status/1895857778180440346" target="_blank" rel="noreferrer">kAI 帮你识别盲点</a>),这里我们就简短说一下。</p><ol><li>写下你不想要的生活是什么样的</li><li>写下你想要的生活是什么样的</li></ol><p>每一项都写出10条以上的要点,并在两者之间来回切换思考。</p><p>这些要点就是你的学习过滤器。</p><p>如果不把这些写下来,你就会分心,也不会有一个能帮助你优化模式识别的参照框架。换句话说,你的大脑不会去注意那些能帮你实现目标的东西。</p><p>然后,试试用我在 X 上找到的<a href="https://app.kortex.co/public/document/7a4a85bb-cdfc-4dbd-92b8-d887fa82d224" target="_blank" rel="noreferrer">这个提示词</a>开启一段对话。它简直是宝藏:</p><p><img src="'+r+'" alt=""></p><p>有了这些背景信息,你就可以让 kAI 对你想要和不想要的生活给出毫不留情的坦诚建议。你可以在需要人生建议的时候,回到那个对话里,就像写一篇持续更新的日记一样。</p><h3 id="_2-拟定一个项目大纲" tabindex="-1">2) 拟定一个项目大纲 <a class="header-anchor" href="#_2-拟定一个项目大纲" aria-label="Permalink to &quot;2) 拟定一个项目大纲&quot;">​</a></h3><p>仔细读一下这句话:</p><p>最好的学习方式,是去动手搭建一个真实世界中的项目,只有在需要时才去查找信息。<em>你学到了多少,直接取决于你在这个项目上取得了多少进展。</em></p><p>当你没完没了地看教程时,你会把大脑塞满噪音和混乱。大部分信息都被浪费掉了。这会导致压力过载、焦虑,并拖慢你学习的速度。</p><p>等真正到了要动手做项目的时候(而这本来才是你学习的唯一理由),你会觉得自己什么都没学到,还得重新去查资料。所以,如果你想学得更快,就跳过“先看教程”这个阶段。先把项目大纲列出来。</p><p>这一点会让一些人感到困惑。</p><p>“项目”可以是任何东西。</p><p>你的健康可以是一个项目。你的生意可以是一个项目。Photoshop 里的一张图片,也可以是一个项目。</p><p>项目,说白了,就是一种实现目标、或朝目标推进的结构化方式。</p><p>它是进一步收窄你的参照框架的一种方式,让你的大脑在学习时能对正确的信息产生偏向。</p><p>再强调一次,这会持续优化你的模式识别能力。</p><p>当你读书、学教程、或与人交谈时,好的多巴胺会涌入你的大脑,提示你某个信息对完成项目很重要。你的潜意识会持续咀嚼这些问题,并把相关的想法送到你的意识层面。</p><p>这就是创作者们所说的“淋浴时的灵光一闪”——当大脑处于“休息”状态时,默认模式网络(Default Mode Network)正在活跃工作。</p><p>达尔文(Darwin)会在专注的时间段里推进他的项目,然后去长时间散步。在这些散步中,他的大脑处于休息状态,而潜在的问题解决方案就会突然浮现在他脑海中。</p><p>当我在做“写newsletter”这个小项目——它嵌套在我事业这个更大的项目里——时,我会在每周初先把这期newsletter的大纲列出来。这就构建了我的参照框架。当我在散步或与人交谈时,一旦有了正确的想法浮现出来,我就能<em>感受到</em>那种兴奋感。</p><p>这时,我会掏出手机,打开<a href="https://kortex.co/" target="_blank" rel="noreferrer">Kortex Chats</a>,连接到那一周的newsletter,把想法存进去,这样下次坐下来在工作时间段写作时,这些素材就已经准备好了。</p><p><strong>这是你启动一个项目的方法:</strong></p><ul><li>选一个能推动你实现前面提到的人生目标的东西去搭建</li><li>创建一份笔记或文档,把脑海中浮现的一切都倾泻出来</li><li>保存3-5个你想效仿的灵感来源(比如如果我把制作一个 YouTube 视频当作一个项目,我会保存3-5个我想以类似方式创作的 YouTube 视频)</li><li>研究这些素材来源,拆解它们的结构或特征</li><li>把项目拆分成若干部分、里程碑、图片、灵感来源,以及你需要了解的知识点</li><li>找一个地方来记录突然浮现的想法,最好是那种不会丢失或遗忘想法的地方</li></ul><p>现在你已经准备好开始了,别急着去学习。</p><h3 id="_3-从你已经知道的东西开始" tabindex="-1">3) 从你已经知道的东西开始 <a class="header-anchor" href="#_3-从你已经知道的东西开始" aria-label="Permalink to &quot;3) 从你已经知道的东西开始&quot;">​</a></h3><p>学习来自于挣扎,而不是死记硬背。</p><p>直接开始这个项目。没错,不要事先看20个教程。让项目本身暴露出你知识上的空白。试着自己去搞明白。等你的大脑最有可能记住答案的时候,再去查找答案。</p><p>无论你是在学 Photoshop 还是学编程,都从你已经知道的东西开始。</p><p>如果你什么都不知道,至少也要试着迈出第一步。下载软件,开始上手摆弄。试着创造出<em>某个东西。任何东西都行。</em>只是要让你的大脑进入一种<em>饥渴</em>想学的状态。否则,你很可能<em>消化</em>不了你查到的那些信息。</p><p>然后,遵循以下流程:</p><ul><li>你不知道该怎么做</li><li>你尝试并失败</li><li>查找答案,或者问 AI</li><li>尝试落地实施这个答案</li><li>重复这个过程,直到项目完成</li><li>如果实在找不到答案,就去请教专家</li></ul><p>几年前,谷歌搜索还是一项技能。</p><p>如今 AI 能够快速提供更相关的信息,提示词技巧(prompting)才是真正的技能。</p><p>不要把 AI 当成一个替你干活的机器,而要把它当成一个创意上的对练搭档。有时候一句话的提示词就能搞定问题,但当涉及到创造性工作时,AI 输出的质量,取决于你自己的水平有多高。</p><p>如果我正在做一个 Photoshop 项目,不知道该怎么去除照片背景,我可以直接问 kAI:“Photoshop 里怎么去除照片的背景”,它就会给我提供具体的操作步骤。</p><p>然后,我还可以接着问更多问题,比如“选区”和“蒙版”是什么,当场就能学会。在 Kortex 桌面应用中,你可以按 Alt 键或 Option+C 打开悬浮聊天窗口,直接问 AI,不需要跳到别的网站,也不用离开当前所在的地方。</p><h3 id="_3-5-当你不想开始时-如何开始" tabindex="-1">3.5) 当你不想开始时,如何开始 <a class="header-anchor" href="#_3-5-当你不想开始时-如何开始" aria-label="Permalink to &quot;3.5) 当你不想开始时,如何开始&quot;">​</a></h3><p>蔡加尼克效应(Zeigarnik Effect)是一种心理现象,指人们记住未完成的任务,比记住已完成的任务更牢。</p><p>也就是说,如果我们没有把项目上的任务做完,反而更容易找到重新开始的动力。</p><p>但要是完全从零开始,你该怎么启动呢?</p><p>我从<a href="https://www.youtube.com/@JustinSung" target="_blank" rel="noreferrer">贾斯汀·宋(Justin Sung)</a>那里学到了一个技巧,他称之为“蔡加尼克²效应”。换句话说,就是在正式开始之前先做一些简单的任务,来模拟出那种“还有任务未完成”的感觉。</p><p>这可以是一种工作前的仪式,比如冲一杯咖啡、整理一下桌子,或者去晨间散步、在手机上随手记几条笔记。</p><p>我喜欢这样理解这件事:把你需要启动的任务,拆解成<em>你能采取的最简单的那个动作。</em></p><p>比如对写作这件事来说,最简单的动作就是坐到你的桌前,打开你的大纲,然后只是把它读一遍。这几乎不需要什么动力。</p><p>现在,如果你想把这个效应发挥到极致,只需打开一个 AI 工具,使用<a href="https://app.kortex.co/public/document/7a4a85bb-cdfc-4dbd-92b8-d887fa82d224" target="_blank" rel="noreferrer">这个提示词</a>:</p><p><img src="'+l+'" alt=""></p><p>我让乔伊(Joey)把这个提示词丢进<a href="https://kortex.co/" target="_blank" rel="noreferrer">kAI</a>里,他稍微改了一下……然后……效果就是这样……</p><p><img src="'+o+'" alt=""></p><p>你也可以试试。</p><h3 id="_4-制定一份学习计划" tabindex="-1">4) 制定一份学习计划 <a class="header-anchor" href="#_4-制定一份学习计划" aria-label="Permalink to &quot;4) 制定一份学习计划&quot;">​</a></h3><p>既然你现在已经有了参照框架、项目大纲,并且已经开始取得进展了——你就可以开始加入一些通用学习和教程内容作为补充了。</p><p>新建一个对话,试试<a href="https://app.kortex.co/public/document/7a4a85bb-cdfc-4dbd-92b8-d887fa82d224" target="_blank" rel="noreferrer">这个提示词</a>:</p><p><img src="'+i+'" alt=""></p><p>对于[主题]这一项,你可以填入任何内容,从 Photoshop、讲故事技巧,到内容创作,都可以。</p><p>在我看来,组织你学习内容的最佳方式,是把时间分成3种类型的时间块:</p><ol><li><strong>30-90分钟的搭建时间</strong> —— 动手做你的项目,只有在需要时才去查资料。</li><li><strong>30-60分钟的学习时间</strong> —— 按照你的学习计划推进,并把学到的东西记下笔记。之后你可以让 kAI 帮你总结这些笔记来进行复习。</li><li><strong>30分钟的散步时间</strong> —— 用来看 YouTube 视频、听有声书或讲座,在散步过程中,一旦有想法浮现,就随手记在手机上。</li></ol><p>这些就是你的基石习惯(keystone habits)。</p><p>没有人会主动给你时间去学习和构建。</p><p>你必须自己抢出时间。把它排进你的日历。早起一小时,或者晚睡一小时。把它变成一种仪式。</p><p>拿起你的咖啡,打开你的大纲,放上一些专注音乐,开始为你想创造的未来铺路。</p><h2 id="写作-系统性地反思你所学到的东西" tabindex="-1">写作,系统性地反思你所学到的东西 <a class="header-anchor" href="#写作-系统性地反思你所学到的东西" aria-label="Permalink to &quot;写作,系统性地反思你所学到的东西&quot;">​</a></h2><p>谜题如下:</p><ul><li>你知道自己想要的未来是什么样的</li><li>你有一个(或一系列)项目能带你去到那里</li><li>你每天都在学习和构建</li></ul><p>但还缺一块拼图。</p><p>而事实证明,这一块拼图,还是一种能<em>进一步</em>提升你学习效果的方法。</p><p>缺失的这一块,就是<em>关心你在构建什么的人</em>。</p><p>我假设你想全职做这件事。</p><p>你学习和构建,是因为你想让它变成某种可持续的生活方式。你想用一种使命——一种痴迷——来取代你的工作或职业。</p><p>要做到这一点,你需要钱。至少要够维持你理想的生活。</p><p>要赚钱,你需要有人关心你在构建什么。</p><p>要让人们关心你在构建什么,你需要公开展示你在做的事情。</p><p>在大多数情况下,最好的方式就是写作。</p><p>在构建的过程中,教授你所知道和正在学习的东西。</p><p>为什么是写作?</p><p>首先,它是媒介的基础。第二,它门槛低,任何人现在就能开始写,不需要视频编辑技能。第三,它的力量远不止建立一群支持者的受众那么简单。</p><p>写作是你系统性反思所学内容的方式。</p><p>当你去教授你所学的东西时,你会暴露出<em>更多</em>知识空白。你会更努力地去理解。你会有更具体的知识需要去研究。</p><p>这正是费曼技巧(Feynman Technique)和门徒效应(Protege Effect)发挥作用的地方。</p><p>费曼技巧是物理学家理查德·费曼(Richard Feynman)推广的一种学习方法。简而言之,它的核心是通过用简单的语言解释一个概念——就好像你在教一个毫无背景知识的人——来深入理解这个概念:</p><ul><li><strong>选择一个概念 –</strong> 选出你想要理解的主题。</li><li><strong>教授它 –</strong> 用简单的语言解释这个概念,就好像你在教一个孩子。</li><li><strong>找出空白 –</strong> 当你难以清晰解释某个部分时,找出你理解薄弱的地方。</li><li><strong>回顾并简化 –</strong> 回到原始材料,重新学习相关概念,然后再尝试用更简单的语言解释一遍。</li></ul><p>这与门徒效应有所重叠,后者的核心观点是:教的人比学的人学到的更多。</p><p>教授你所学的东西,会促使你用自己的方式去理解自己的经历。它会暴露出你知识中更多的空白,从而增强模式识别的效果。生活会变得更加持续地令人愉悦、更加充满意外之喜,因为你不再需要靠分心娱乐来获得快乐。</p><p>我们要如何把这两者,与你已经在做的学习方式结合起来?</p><p>方法就是:在互联网上写作。</p><p>我们几乎在每一期通讯里都会谈到这一点,但我说的不是让你变成一个内容创作者。</p><p>我说的是,把社交媒体当作你的公开日记来对待。</p><p>这样一来,你至少<em>有机会</em>吸引到潜在的支持者、客户、雇主、投资人、团队成员,以及任何你需要用来到达理想生活的其他人。</p><p>这与其说是在积累粉丝,不如说是在把你的作品呈现在别人面前。就像你想认识新朋友一样,如果你不走出家门,这事永远不会发生,而你只会变得越来越怨愤和恼怒,想不明白自己为什么总是孤身一人。原因很明显……因为你根本没给别人一个了解你或关心你的机会。你成功的概率是零。</p><p>以下是我给刚开始的人的建议:</p><ul><li>每周写一期通讯,总结你学到的东西</li><li>记住,是教给他们,不要把它变成一堆枯燥信息的堆砌。</li><li>在 X、Threads 或 LinkedIn(这些是易于上手的写作平台)上发帖</li><li>谈谈你的观点、信念、个人经历,以及你正在学习和构建的东西</li><li>把“社交媒体”当作一项你需要学习的技能,用这封信里教的同样方法去学</li><li>每天早上再加一个 30-60 分钟的时间段用于写作</li><li>在写作时请 kAI 帮忙,比如:“你是一个擅长撰写吸引人社交帖子的专家。开始写一篇关于[主题]的帖子,最好的方式是什么?”然后从那里继续下去。</li></ul><p>就我个人而言,写作改变了我的人生。</p><p>我曾是一名自由职业网页设计师,在那之前尝试的每一个业务都失败了。</p><p>我开始做社交媒体,是因为我厌倦了通过陌生开发去拉客户。</p><p>随着我不断坚持下去,我意识到写作在把我呈现在正确的人面前这件事上,有多么强大的力量(这样我就不必被那么多人拒绝了,反而是人们主动找上门来)。</p><p>但这不仅仅关乎自由职业的工作。</p><p>更关乎我学到了多少东西。</p><p>每次我点击发布,我都感觉自己学到了新东西。</p><p>我能看到一条路径,通向我小时候一直崇拜的那种“聪明”的人。</p><p>我写得越多,内在和外在发生的好事就越多。</p><p>我希望你也能体验到这一点。</p><p>现在,你不需要报名参加“作家训练营”(Writer&#39;s Bootcamp),但它是你可以纳入上面所说的“学习计划”中的一个选项。</p><p>开营日期是 3 月 4 日。距现在还有 3 天。所以,如果你想学习通讯、Threads、帖子、YouTube 视频脚本的方方面面,以及在 Kortex 中构建一个 AI 驱动的第二大脑来存放想法,<a href="https://bootcamp.kortex.co/" target="_blank" rel="noreferrer">可以考虑在这里报名。</a></p><p>感谢阅读。</p><p>——Dan</p><hr><p><a href="/en/letters/how-to-learn-anything-10x-faster-than-anyone-with-ai">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',141))])}const T=n(u,[["render",b]]);export{I as __pageData,T as default};
